export function FeedbackPopover({ flagKey = "${n}", ldClient }) {
  const [isOpen, setIsOpen] = useState(false);
  const [feedback, setFeedback] = useState("");
  const [sentiment, setSentiment] = useState(undefined);

  const handleSubmit = () => {
    sendFeedback(
      ldClient,
      flagKey,
      feedback,
      sentiment,
      "${t}"
    );
    setIsOpen(false);
    setFeedback("");
    setSentiment(undefined);
  };

  return (
    <div style={{ position: "relative", display: "inline-block" }}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        style={{
          backgroundColor: "black",
          color: "white",
          border: "none",
          borderRadius: "0.25rem",
          padding: "0.5rem 1rem",
          cursor: "pointer",
        }}
      >
        Give feedback
      </button>
      {isOpen && (
        <div
          style={{
            position: "absolute",
            top: "100%",
            left: 0,
            marginTop: "0.5rem",
            backgroundColor: "white",
            border: "1px solid #ccc",
            borderRadius: "0.25rem",
            padding: "16px",
            boxSizing: "border-box",
            width: "300px",
            zIndex: 1000,
          }}
        >
          <textarea
            name="feedback"
            value={feedback}
            onChange={(e) => setFeedback(e.target.value)}
            placeholder="${t}"
            rows={3}
            style={{
              width: "100%",
              padding: "0.5rem",
              marginBottom: "0.5rem",
              boxSizing: "border-box",
              border: "1px solid #ccc",
              borderRadius: "0.25rem",
              fontFamily: "sans-serif",
            }}
          />
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div style={{ display: "flex", gap: "0.25rem" }}>
              <button
                onClick={() =>
                  setSentiment(
                    sentiment === "positive" ? undefined : "positive"
                  )
                }
                aria-label="Thumbs up"
                style={{
                  cursor: "pointer",
                  background: sentiment === "positive" ? "#eee" : "none",
                  border: "none",
                  borderRadius: "0.25rem",
                  padding: "0.25rem 0.5rem",
                }}
              >
                <ThumbsUpIcon />
              </button>
              <button
                onClick={() =>
                  setSentiment(
                    sentiment === "negative" ? undefined : "negative"
                  )
                }
                aria-label="Thumbs down"
                style={{
                  cursor: "pointer",
                  background: sentiment === "negative" ? "#eee" : "none",
                  border: "none",
                  borderRadius: "0.25rem",
                  padding: "0.25rem 0.5rem",
                }}
              >
                <ThumbsDownIcon />
              </button>
            </div>
            <button
              onClick={handleSubmit}
              style={{
                backgroundColor: "black",
                color: "white",
                border: "none",
                borderRadius: "0.25rem",
                padding: "0.5rem 1rem",
                cursor: "pointer",
              }}
            >
              Send
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

